        }

        for (Location loc : getField().adjacentLocations(getLocation())) {
            Object animal = getField().getObjectAt(loc);
            if (animal instanceof Lion) {
                Lion lion = (Lion) animal;
                if (!(((lion.isMale() && isMale())) || ((!lion.isMale() && !isMale())))) {
                    return true;
                }
            }
        }
        return false;
    }
